/**
 * `scripts/lib/pip-lock.mjs` (hash locks generated by `npm run runtime:pin`): argument
 * building, the joint pip report → per-engine locks derivation and the `--verify`
 * checks. No network: pip is never run.
 */
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { describe, it } from 'node:test';
import {
  PIP_PLATFORM_TAGS,
  dependencyName,
  findPython,
  lockPlatforms,
  lockProblems,
  locksFromReport,
  parseDependency,
  parsePipVersion,
  pinnedRequirements,
  pipReportArgs,
  platformsNeedingLocks,
  pruneInvalidLocks,
  pythonCandidates,
  pythonSeries,
  readPipReport,
  setPlatformLocks,
  unsupportedLock,
  unsupportedPlatforms,
  type ManifestLike
} from '../scripts/lib/pip-lock.mjs';

const ROOT = path.resolve(import.meta.dirname, '..');
const A = 'a'.repeat(64);
const B = 'b'.repeat(64);

function item(name: string, version: string, requires: string[] = [], overrides: Record<string, unknown> = {}) {
  return {
    download_info: {
      url: `https://files.pythonhosted.org/packages/xx/${name}-${version}-py3-none-any.whl`,
      archive_info: { hash: `sha256=${A}`, hashes: { sha256: A } }
    },
    is_direct: false,
    requested: name === 'yt-dlp' || name === 'gallery-dl',
    metadata: { name, version, metadata_version: '2.1', ...(requires.length > 0 ? { requires_dist: requires } : {}) },
    ...overrides
  };
}

const report = (install: unknown[]) => ({ version: '1', pip_version: '24.0', install, environment: {} });
const PINS = {
  'gallery-dl': { requirement: 'gallery-dl', version: '1.32.9' },
  'yt-dlp': { requirement: 'yt-dlp[default]', version: '2025.11.12' }
};

/** What pip reports for `gallery-dl==1.32.9 yt-dlp[default]==2025.11.12` (trimmed). */
const YTDLP_REQUIRES = [
  'brotli; implementation_name == "cpython" and extra == "default"',
  'certifi; extra == "default"',
  'requests (<3,>=2.32.2) ; extra == "default"',
  'websockets>=13.0; extra == "default"',
  'yt-dlp[curl-cffi]; extra == "build"',
  'pyinstaller>=6.13.0; extra == "pyinstaller"'
];
const JOINT_ITEMS = [
  item('gallery-dl', '1.32.9', ['requests>=2.11.0', 'yt-dlp; extra == "video"']),
  item('yt-dlp', '2025.11.12', YTDLP_REQUIRES),
  item('requests', '2.32.5', [
    'charset_normalizer<4,>=2',
    'idna<4,>=2.5',
    'certifi>=2017.4.17',
    'PySocks; extra == "socks"'
  ]),
  item('Brotli', '1.1.0', [], {
    download_info: {
      url: 'https://files.pythonhosted.org/p/Brotli-1.1.0-cp312-cp312-win_amd64.whl',
      archive_info: { hash: `sha256=${B.toUpperCase()}` }
    }
  }),
  item('certifi', '2025.8.3'),
  item('charset_normalizer', '3.4.4'),
  item('idna', '3.10'),
  item('websockets', '15.0.1')
];
const JOINT = report(JOINT_ITEMS);

describe('pip lock generation', () => {
  it('resolves every engine pin of a platform in one dry-run report', () => {
    const args = pipReportArgs({
      requirements: pinnedRequirements(PINS),
      platform: 'win32-x64',
      pythonVersion: pythonSeries('3.12.14'),
      reportFile: '/tmp/r.json',
      targetDir: '/tmp/t'
    });
    assert.deepEqual(args, [
      '-m',
      'pip',
      'install',
      '--dry-run',
      '--ignore-installed',
      '--isolated',
      '--disable-pip-version-check',
      '--no-input',
      '--quiet',
      '--report',
      '/tmp/r.json',
      '--only-binary=:all:',
      '--platform',
      'win_amd64',
      '--python-version',
      '3.12',
      '--implementation',
      'cp',
      '--target',
      '/tmp/t',
      'gallery-dl==1.32.9',
      'yt-dlp[default]==2025.11.12'
    ]);
    const base = { pythonVersion: '3.12', reportFile: 'r', targetDir: 't' };
    assert.throws(() => pipReportArgs({ ...base, requirements: ['x==1'], platform: 'plan9-x64' }));
    assert.throws(() => pipReportArgs({ ...base, requirements: [], platform: 'linux-x64' }));
    assert.throws(() => pythonSeries('latest'));
  });

  it('has a platform tag for every platform with a managed Python in the manifest', () => {
    const file = path.join(ROOT, 'src/host/infrastructure/runtime/runtime-manifest.json');
    const manifest = JSON.parse(readFileSync(file, 'utf8')) as ManifestLike;
    const platforms = lockPlatforms(manifest);
    assert.ok(platforms.length > 0);
    for (const platform of platforms) assert.ok(PIP_PLATFORM_TAGS[platform], platform);
  });

  it('reads every wheel of the report with its SHA-256 and dependency names', () => {
    const items = readPipReport(JOINT);
    assert.deepEqual(
      items.map((i) => `${i.name}==${i.version}`),
      [
        'brotli==1.1.0',
        'certifi==2025.8.3',
        'charset-normalizer==3.4.4',
        'gallery-dl==1.32.9',
        'idna==3.10',
        'requests==2.32.5',
        'websockets==15.0.1',
        'yt-dlp==2025.11.12'
      ]
    );
    assert.deepEqual(items[0]?.sha256, [B]);
    assert.deepEqual(
      items.find((i) => i.name === 'requests')?.requires.map((d) => d.name),
      ['charset-normalizer', 'idna', 'certifi', 'pysocks']
    );
    assert.deepEqual(parseDependency('websockets (>=13.0) ; extra == "default"'), {
      name: 'websockets',
      extras: [],
      whenExtras: ['default']
    });
    assert.deepEqual(parseDependency("Yt_Dlp[curl_cffi, Default]>=1; python_version>'3.9' or extra=='Build'"), {
      name: 'yt-dlp',
      extras: ['curl-cffi', 'default'],
      whenExtras: ['build']
    });
    assert.equal(dependencyName('Brotli; implementation_name == "cpython"'), 'brotli');
    assert.equal(dependencyName(42), null);
  });

  it('follows extras requested by a dependency spec (requests[socks])', () => {
    const joint = report([
      item('gallery-dl', '1.32.9', ['requests[socks]>=2']),
      item('yt-dlp', '2025.11.12'),
      item('requests', '2.32.5', ['PySocks!=1.5.7,>=1.5.6; extra == "socks"']),
      item('PySocks', '1.7.1')
    ]);
    const locks = locksFromReport(joint, PINS);
    assert.deepEqual(
      locks['gallery-dl']?.map((w) => w.name),
      ['gallery-dl', 'pysocks', 'requests']
    );
    assert.deepEqual(
      locks['yt-dlp']?.map((w) => w.name),
      ['yt-dlp']
    );
  });

  it('splits the joint report into consistent per-engine locks', () => {
    const locks = locksFromReport(JOINT, PINS);
    assert.deepEqual(
      locks['gallery-dl']?.map((w) => w.name),
      ['certifi', 'charset-normalizer', 'gallery-dl', 'idna', 'requests']
    );
    assert.deepEqual(
      locks['yt-dlp']?.map((w) => w.name),
      ['brotli', 'certifi', 'charset-normalizer', 'idna', 'requests', 'websockets', 'yt-dlp']
    );
    const shared = (engine: string) => locks[engine]?.find((w) => w.name === 'requests');
    assert.deepEqual(shared('gallery-dl'), shared('yt-dlp'), 'one resolution: shared dependencies are identical');
    assert.deepEqual(Object.keys(locks['yt-dlp']?.[0] ?? {}), ['name', 'version', 'sha256']);

    // PyPI normalizes `2026.01.15` to `2026.1.15` in the metadata.
    const zeros = locksFromReport(report([item('yt-dlp', '2026.1.15')]), {
      y: { requirement: 'yt-dlp', version: '2026.01.15' }
    });
    assert.equal(zeros['y']?.length, 1);
  });

  it('refuses reports it cannot trust, that miss a pin or hold a wheel no engine needs', () => {
    const wheelAt = (url: string, archive: Record<string, unknown>) => ({
      download_info: { url, archive_info: archive }
    });
    const bad: Array<[string, unknown]> = [
      ['not an object', null],
      ['old format', { version: '0', install: [item('yt-dlp', '2025.11.12')] }],
      ['empty', report([])],
      [
        'sdist',
        report([item('yt-dlp', '2025.11.12', [], wheelAt('https://x/yt_dlp-1.tar.gz', { hashes: { sha256: A } }))])
      ],
      [
        'http',
        report([item('yt-dlp', '2025.11.12', [], wheelAt('http://x/y-1-py3-none-any.whl', { hashes: { sha256: A } }))])
      ],
      ['no hash', report([item('yt-dlp', '2025.11.12', [], wheelAt('https://x/y-1-py3-none-any.whl', {}))])],
      [
        'md5 only',
        report([item('yt-dlp', '2025.11.12', [], wheelAt('https://x/y-1-py3-none-any.whl', { hash: 'md5=x' }))])
      ],
      ['option as name', report([...JOINT.install, item('--index-url', '1.0')])],
      ['duplicate', report([...JOINT.install, item('Yt_Dlp', '2025.11.12')])],
      ['other version', report([item('gallery-dl', '1.32.9'), item('yt-dlp', '2025.10.22')])],
      ['engine missing', report([item('gallery-dl', '1.32.9')])],
      ['orphan wheel', report([...JOINT.install, item('colorama', '0.4.6')])]
    ];
    for (const [label, input] of bad) assert.throws(() => locksFromReport(input, PINS), label);
  });
});

describe('pip lock checks (--verify) and manifest updates', () => {
  const wheel = (name: string, version: string) => ({ name, version, sha256: [A] });
  function manifestWith(
    gdl: Record<string, unknown> | undefined,
    ytdlp: Record<string, unknown> | undefined
  ): ManifestLike {
    return JSON.parse(
      JSON.stringify({
        tools: { python: { assets: { 'linux-x64': {}, 'win32-x64': {} } } },
        pythonPackages: {
          'gallery-dl': { requirement: 'gallery-dl', version: '1.32.9', ...(gdl ? { lock: gdl } : {}) },
          'yt-dlp': { requirement: 'yt-dlp[default]', version: '2025.11.12', ...(ytdlp ? { lock: ytdlp } : {}) }
        }
      })
    ) as ManifestLike;
  }

  it('reports missing, stale and conflicting locks', () => {
    const manifest = manifestWith(
      {
        'linux-x64': [wheel('gallery-dl', '1.32.9'), wheel('requests', '2.32.4')],
        'win32-x64': [wheel('gallery-dl', '1.32.9')]
      },
      {
        'linux-x64': [wheel('yt-dlp', '2025.11.12'), wheel('requests', '2.32.5')],
        'win32-x64': [wheel('yt-dlp', '2025.10.22')]
      }
    );
    assert.deepEqual(lockProblems(manifest), [
      { engine: 'yt-dlp', platform: 'linux-x64', reason: 'requests locked at 2.32.4 (gallery-dl) and 2.32.5 (yt-dlp)' },
      { engine: 'yt-dlp', platform: 'win32-x64', reason: 'stale hash lock (pinned 2025.11.12)' }
    ]);
    assert.deepEqual(
      lockProblems(manifestWith(undefined, undefined)).map((p) => `${p.engine} ${p.platform} ${p.reason}`),
      [
        'gallery-dl linux-x64 no hash lock',
        'yt-dlp linux-x64 no hash lock',
        'gallery-dl win32-x64 no hash lock',
        'yt-dlp win32-x64 no hash lock'
      ]
    );
  });

  it('accepts a platform marked unsupported for every engine, not for some only', () => {
    const marker = unsupportedLock('pip failed:\n  ERROR: No matching distribution found for brotli');
    assert.deepEqual(marker, { unsupported: 'pip failed: ERROR: No matching distribution found for brotli' });
    assert.equal(unsupportedLock('x'.repeat(500)).unsupported.length, 280);
    const locked = { 'linux-x64': [wheel('gallery-dl', '1.32.9')] };
    const both = manifestWith(
      { ...locked, 'win32-x64': marker },
      { 'linux-x64': [wheel('yt-dlp', '2025.11.12')], 'win32-x64': marker }
    );
    assert.deepEqual(lockProblems(both), []);
    assert.deepEqual(unsupportedPlatforms(both), [{ platform: 'win32-x64', reason: marker.unsupported }]);
    const some = manifestWith({ ...locked, 'win32-x64': marker }, { 'linux-x64': [wheel('yt-dlp', '2025.11.12')] });
    assert.deepEqual(lockProblems(some), [
      { engine: 'yt-dlp', platform: 'win32-x64', reason: 'python mode marked unsupported for other engines only' }
    ]);
  });

  it('relocks every engine of a platform after a single-engine bump, in one pass', () => {
    const fresh = locksFromReport(JOINT, PINS);
    const manifest = manifestWith({ 'linux-x64': fresh['gallery-dl'] }, { 'linux-x64': fresh['yt-dlp'] });
    const ytdlp = manifest.pythonPackages['yt-dlp'];
    assert.ok(ytdlp);
    manifest.pythonPackages['yt-dlp'] = { ...ytdlp, version: '2026.01.15' };
    assert.deepEqual(platformsNeedingLocks(manifest), ['linux-x64', 'win32-x64']);

    const bumped = report(
      JOINT_ITEMS.map((entry) =>
        entry.metadata.name === 'yt-dlp' ? item('yt-dlp', '2026.1.15', YTDLP_REQUIRES) : entry
      )
    );
    for (const platform of platformsNeedingLocks(manifest))
      setPlatformLocks(manifest, platform, locksFromReport(bumped, manifest.pythonPackages));
    assert.deepEqual(lockProblems(manifest), [], 'a single run leaves nothing to relock');
  });

  it('prunes the locks the app would reject, keeping missing ones and unsupported markers', () => {
    const marker = unsupportedLock('no wheel');
    const manifest = manifestWith(
      { 'linux-x64': [wheel('gallery-dl', '1.32.9'), wheel('requests', '2.32.4')], 'win32-x64': marker },
      { 'linux-x64': [wheel('yt-dlp', '2025.11.12'), wheel('requests', '2.32.5')], 'win32-x64': marker }
    );
    const messages = pruneInvalidLocks(manifest);
    assert.equal(messages.length, 1);
    assert.match(messages[0] ?? '', /^linux-x64 lock: yt-dlp: requests locked at/);
    assert.deepEqual(manifest.pythonPackages['gallery-dl']?.lock, { 'win32-x64': marker });
    assert.deepEqual(manifest.pythonPackages['yt-dlp']?.lock, { 'win32-x64': marker });
    assert.deepEqual(pruneInvalidLocks(manifestWith(undefined, undefined)), [], 'a missing lock is valid for the app');
  });
});

describe('Python discovery for runtime:pin', () => {
  it('looks for Python in $PYTHON, py -3 (Windows), python3, python and requires pip >= 23.0', async () => {
    assert.deepEqual(
      pythonCandidates({ PYTHON: 'C:\\Py\\python.exe' }, 'win32').map((c) => [c.command, ...c.args].join(' ')),
      ['C:\\Py\\python.exe', 'py -3', 'python3', 'python']
    );
    assert.deepEqual(
      pythonCandidates({}, 'linux').map((c) => c.command),
      ['python3', 'python']
    );
    assert.deepEqual(parsePipVersion('pip 24.2 from /usr/lib/python3/dist-packages/pip (python 3.12)\n'), {
      pip: [24, 2],
      python: '3.12'
    });
    assert.equal(parsePipVersion('Python was not found'), null);

    const outputs: Record<string, { ok: boolean; stdout: string }> = {
      python3: { ok: true, stdout: 'pip 22.3.1 from /x/pip (python 3.11)' },
      python: { ok: true, stdout: 'pip 23.0 from /y/pip (python 3.12)' }
    };
    const found = await findPython({}, 'linux', async (command) => outputs[command] ?? { ok: false, stdout: '' });
    assert.equal(found.python?.label, 'python');
    assert.equal(found.python?.pythonSeries, '3.12');
    assert.deepEqual(found.tried, ['python3: pip 22.3 is older than 23.0']);
    const none = await findPython({ PYTHON: '/nope' }, 'linux', async () => ({ ok: false, stdout: '' }));
    assert.equal(none.python, null);
    assert.equal(none.tried.length, 3);
  });
});
